create or replace function platform.drill_def__ai_calls()
returns jsonb
language sql
immutable
set search_path to 'pg_catalog'
as $function$
  select $drill${"key":"ai_calls","fact":"ai_calls","mode":"definer","grain":"one row per model call (chat.request): the model that answered, its provider, tokens, cost, latency and status","label":"AI model calls","lanes":["platform","organization","mine"],"paths":[{"key":"what","label":"What","levels":["provider","model"]},{"key":"who","label":"Who","levels":["organization","person","session"]},{"key":"thread","label":"Conversation","levels":["conversation","request","iteration"]},{"key":"when","label":"When","levels":["at:day","at:hour","bucket_10m"]}],"views":[{"key":"cx_by_model","label":"Usage by model","question":{"by":["model","provider"],"show":["calls","cost","tokens_in","tokens_out","tokens_cached","tokens_total","latency"],"sort":{"key":"calls","direction":"desc"}}},{"key":"cx_by_provider","label":"Cost by provider","question":{"by":["provider"],"show":["calls","cost","tokens_total"],"sort":{"key":"calls","direction":"desc"}}},{"key":"cx_by_day","label":"Daily cost and tokens","question":{"by":["at:day"],"show":["calls","cost","tokens_in","tokens_out","tokens_cached"],"sort":{"key":"at:day","direction":"asc"}}},{"key":"cx_by_origin","label":"Cost by origin","question":{"by":["origin"],"show":["calls","cost","tokens_in","tokens_out","tokens_cached","tokens_total"],"sort":{"key":"cost","direction":"desc"}}},{"key":"cx_cost_share","label":"Cost share by model","question":{"by":["model","provider"],"show":["cost","calls"],"sort":{"key":"cost","direction":"desc"}}},{"key":"cx_latency","label":"Latency by model","question":{"by":["model","provider"],"show":["latency","latency_median","calls"],"sort":{"key":"latency","direction":"desc"}}},{"key":"reconcile_calls","label":"Model-call cost by whether the ledger holds the request (to reconcile with the ledger)","question":{"by":["request_in_ledger"],"show":["cost","calls"],"sort":{"key":"cost","direction":"desc"}}}],"detail":{"open":"/administration/chat/cx-dashboard/usage","columns":["created_at","model","provider","status","iteration","cost","tokens_in","tokens_out","latency_ms"]},"default":{"by":["model"],"path":"what","show":["calls","cost","latency"],"sort":{"key":"cost","direction":"desc"},"window":{"key":"at","preset":"30d"}},"measures":[{"of":"calls","op":"sum","key":"calls","unit":"count","label":"Calls","additive":true},{"of":"cost","op":"sum","key":"cost","unit":"usd","label":"Cost","additive":true},{"of":"tokens_in","op":"sum","key":"tokens_in","unit":"tokens","label":"Input tokens","additive":true},{"of":"tokens_out","op":"sum","key":"tokens_out","unit":"tokens","label":"Output tokens","additive":true},{"of":"tokens_cached","op":"sum","key":"tokens_cached","unit":"tokens","label":"Cached tokens","additive":true},{"of":"tokens_total","op":"sum","key":"tokens_total","unit":"tokens","label":"Total tokens","additive":true},{"of":"latency_ms","op":"avg","key":"latency","unit":"ms","label":"Average latency","additive":false},{"of":"latency_ms","op":"median","key":"latency_median","unit":"ms","label":"Median latency","additive":false},{"of":"unpriced_calls","op":"sum","key":"unpriced_calls","unit":"count","label":"Calls with no price","additive":true},{"of":"request_id","op":"count_distinct","key":"requests","unit":"count","label":"Requests","additive":false},{"of":"person_id","op":"count_distinct","key":"people","unit":"count","label":"People","additive":false},{"op":"ratio","den":"calls","key":"cost_per_call","num":["cost"],"unit":"usd","label":"Cost per call"}],"dimensions":[{"key":"organization","from":"organization_id","kind":"relation","label":"Organization","relation":{"token":"organization"}},{"key":"person","from":"person_id","kind":"relation","label":"Person","relation":{"token":"user","person":true}},{"key":"agent","from":"agent_id","kind":"relation","label":"Agent","relation":{"token":"agent"},"cardinality":"medium"},{"key":"model","from":"model","kind":"text","label":"Model","cardinality":"medium"},{"key":"provider","from":"provider","kind":"choice","label